package com.novaguard.surveillance

import com.facebook.react.bridge.Promise
import com.facebook.react.bridge.ReactApplicationContext
import java.util.concurrent.Executors

/**
 * JS entry point for {@link SurveillanceService}.
 *
 * `NativeSurveillanceServiceSpec` is generated by codegen from
 * `src/specs/NativeSurveillanceService.ts` (see `codegenConfig` in package.json).
 */
class SurveillanceServiceModule(reactContext: ReactApplicationContext) :
  NativeSurveillanceServiceSpec(reactContext) {

  override fun getName(): String = NAME

  override fun start(title: String, body: String) {
    // Android only allows a camera-type foreground service to be started while
    // the app is visible, which is the case here: monitoring is started by a tap.
    SurveillanceService.start(reactApplicationContext, title, body)
  }

  override fun stop() {
    SurveillanceService.stop(reactApplicationContext)
  }

  override fun isRunning(): Boolean = SurveillanceService.isRunning

  override fun lastError(): String = SurveillanceService.lastError.orEmpty()

  override fun notifyDetection(title: String, body: String) {
    DetectionNotifier.notify(reactApplicationContext, title, body)
  }

  override fun dismissDetection() {
    DetectionNotifier.dismiss(reactApplicationContext)
  }

  override fun shareRecording(path: String): Boolean =
    ClipSharing.share(reactApplicationContext, path)

  override fun openDetectionChannelSettings() {
    DetectionNotifier.openChannelSettings(reactApplicationContext)
  }

  /**
   * Off the calling thread on purpose: this opens and parses the container to
   * decode one frame, and the JS thread it is called from is the one about to
   * file the event.
   *
   * Never rejects. A clip with no readable frame resolves to "", and the card
   * keeps the placeholder it already draws for a clip recorded screen-off.
   */
  override fun extractThumbnail(clipPath: String, promise: Promise) {
    thumbnails.execute { promise.resolve(ClipThumbnail.extract(clipPath)) }
  }

  companion object {
    const val NAME = "SurveillanceService"

    // One thread, shared: clips are filed one at a time, and a pool would only
    // let several decodes compete for memory on the phone doing the watching.
    private val thumbnails = Executors.newSingleThreadExecutor()
  }
}
